def nodes_at_distance(n: int, edges: list[list[int]], start: int, t: int) -> int:
    from collections import defaultdict, deque
    adj = defaultdict(list)
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)
    q = deque([(start, 0)])
    visited = {start}
    count = 0
    while q:
        curr, dist = q.popleft()
        if dist == t:
            count += 1
        elif dist < t:
            for nxt in adj[curr]:
                if nxt not in visited:
                    visited.add(nxt)
                    q.append((nxt, dist + 1))
    return count
